using System.Collections.Concurrent;
using System.Text.Json;
using Qubic.Crypto;

namespace Qubic.Core.Contracts.Metadata;

/// <summary>
/// Runtime contract metadata: function/procedure ids and input/output struct layouts.
/// Starts from the built-in contracts (embedded <c>builtin-contracts.json</c>, generated by
/// Qubic.ContractGen from qubic-core headers) and accepts additional contracts parsed from
/// C++ headers at runtime — e.g. a contract under development on a local AIO testnet.
/// Registered contracts override built-ins with the same index.
/// </summary>
public sealed class ContractCatalog
{
    private const string ResourceName = "Qubic.Core.Contracts.Metadata.builtin-contracts.json";

    private static readonly Lazy<IReadOnlyList<ContractDefinition>> BuiltinLazy = new(LoadBuiltin);
    private static readonly IQubicCrypt Crypt = new QubicCrypt();

    private readonly ConcurrentDictionary<int, ContractDefinition> _registered = new();

    /// <summary>Contracts shipped with this library.</summary>
    public static IReadOnlyList<ContractDefinition> Builtin => BuiltinLazy.Value;

    /// <summary>Contracts registered on this catalog (imported headers).</summary>
    public IReadOnlyCollection<ContractDefinition> Registered => _registered.Values.ToList();

    /// <summary>All known contracts, registered first-class, ordered by index.</summary>
    public IReadOnlyList<ContractDefinition> All =>
        Builtin.Where(b => !_registered.ContainsKey(b.ContractIndex))
            .Concat(_registered.Values)
            .OrderBy(c => c.ContractIndex)
            .ToList();

    public ContractDefinition? Get(int contractIndex) =>
        _registered.TryGetValue(contractIndex, out var r) ? r : Builtin.FirstOrDefault(c => c.ContractIndex == contractIndex);

    public void Register(ContractDefinition contract) => _registered[contract.ContractIndex] = contract;

    public bool Unregister(int contractIndex) => _registered.TryRemove(contractIndex, out _);

    public void ClearRegistered() => _registered.Clear();

    /// <summary>
    /// Parses a contract header (C++ source text) and registers it.
    /// <paramref name="cppStructName"/> is the contract struct (e.g. <c>MYCONTRACT</c>); when null it is
    /// taken from the first <c>struct X : public ContractBase</c> in the source.
    /// </summary>
    public ContractDefinition ImportHeader(string source, int contractIndex, string? displayName = null,
        string? cppStructName = null, List<string>? warnings = null)
    {
        cppStructName ??= DetectContractStruct(source)
            ?? throw new FormatException("No 'struct X : public ContractBase' found in the header.");
        var parser = new CppHeaderParser();
        var def = parser.ParseText(source, contractIndex, displayName ?? cppStructName, cppStructName);
        warnings?.AddRange(parser.Warnings);
        Register(def);
        return def;
    }

    /// <summary>Finds the contract struct name declared as <c>struct NAME : public ContractBase</c>.</summary>
    public static string? DetectContractStruct(string source)
    {
        var m = System.Text.RegularExpressions.Regex.Match(source, @"struct\s+(\w+)\s*:\s*public\s+ContractBase");
        return m.Success ? m.Groups[1].Value : null;
    }

    /// <summary>
    /// Contract index encoded in a contract identity's public key (index in bytes 0-1, rest zero),
    /// or null if <paramref name="publicKey"/> is not a contract address.
    /// </summary>
    public static int? GetContractIndex(ReadOnlySpan<byte> publicKey)
    {
        if (publicKey.Length != 32) return null;
        if (publicKey[2..].IndexOfAnyExcept((byte)0) >= 0) return null;
        var index = publicKey[0] | (publicKey[1] << 8);
        return index == 0 ? null : index;
    }

    public static int? GetContractIndex(string identity)
    {
        try
        {
            return identity.Length == 60 ? GetContractIndex(Crypt.GetPublicKeyFromIdentity(identity)) : null;
        }
        catch { return null; }
    }

    /// <summary>
    /// Decodes a transaction payload sent to a contract, or returns null if the destination is not
    /// a contract / the contract is unknown. Unknown procedures decode with no fields.
    /// </summary>
    public DecodedCall? DecodeProcedureCall(int contractIndex, int inputType, ReadOnlySpan<byte> payload)
    {
        var contract = Get(contractIndex);
        if (contract == null) return null;
        var proc = contract.Procedures.FirstOrDefault(p => p.InputType == inputType);
        if (proc == null)
            return new DecodedCall(contractIndex, contract.CSharpName, null, inputType, [], -1, payload.Length);
        var expected = ContractLayout.SizeOf(proc.Input);
        return new DecodedCall(contractIndex, contract.CSharpName, proc.Name, inputType,
            ContractCodec.Decode(proc.Input, payload), expected, payload.Length);
    }

    /// <summary>Decodes a function's output bytes.</summary>
    public IReadOnlyList<DecodedField>? DecodeFunctionOutput(int contractIndex, int inputType, ReadOnlySpan<byte> output)
    {
        var fn = Get(contractIndex)?.Functions.FirstOrDefault(f => f.InputType == inputType);
        return fn == null ? null : ContractCodec.Decode(fn.Output, output);
    }

    public static string Serialize(IEnumerable<ContractDefinition> contracts) =>
        JsonSerializer.Serialize(contracts, new JsonSerializerOptions
        {
            WriteIndented = false,
            DefaultIgnoreCondition = System.Text.Json.Serialization.JsonIgnoreCondition.WhenWritingDefault
        });

    public static List<ContractDefinition> Deserialize(string json) =>
        JsonSerializer.Deserialize<List<ContractDefinition>>(json) ?? [];

    private static IReadOnlyList<ContractDefinition> LoadBuiltin()
    {
        using var stream = typeof(ContractCatalog).Assembly.GetManifestResourceStream(ResourceName);
        if (stream == null) return [];
        using var reader = new StreamReader(stream);
        return Deserialize(reader.ReadToEnd());
    }
}
